prts.feedbackvariables:
if listp(ans1) then ant1:ans1 else ant1:[ans1];
an1:[];
for i:1 while i<=length(ant1) do (if matrixp(ant1[i]) then (if is(length(ant1[i])=n) then an1:append(an1,[ant1[i]]) else an1:append(an1,[transpose(ant1[i])])) else an1:append(an1,[transpose(matrix(ant1[i]))]));

validInput: collistp(an1);
ans: if (collistp(ans1)) then ans1 else (if (collistp(an1)) then an1 else []);

notinKer: leavefalses(lambda([v],is(abs(prod(A.v,A.v))<10^(-6))),ans);
independent: not dependentvects(ans);
spanningKer: inSpan(ans,kerbase);

nonunits: leavefalses(unitvectp,ans);

perpidxs(idxs):= perpp(ans[idxs[1]],ans[idxs[2]]);
nonperp: leavefalses(perpidxs, pairs(length(ans)));
nonperpex: if (nonperp=[]) then 0 else first(nonperp);

perfect: is(validInput and notinKer=[] and independent and spanningKer and nonunits=[] and nonperp=[]);

if listp(ans2) then ant2:ans2 else ant2:[ans2];
an2:[];
for i:1 while i<=length(ant2) do (if matrixp(ant2[i]) then (if is(length(ant2[i])=n) then an2:append(an2,[ant2[i]]) else an2:append(an2,[transpose(ant2[i])])) else an2:append(an2,[transpose(matrix(ant2[i]))]));

validInput: collistp(an2);
ans: if (collistp(ans2)) then ans2 else (if (collistp(an2)) then an2 else []);

notinIm: leavefalses(lambda([v],inSpan2(imbase,[v])),ans);
independent: not dependentvects(ans);
spanningIm: inSpan(ans,imbase) or (independent and is(notinIm=[]) and length(imbase)=length(ans));

nonunits: leavefalses(unitvectp,ans);

perpidxs(idxs):= perpp(ans[idxs[1]],ans[idxs[2]]);
nonperp: leavefalses(perpidxs, pairs(length(ans)));
nonperpex: if (nonperp=[]) then 0 else first(nonperp);

perfect: is(validInput and notinIm=[] and independent and spanningIm and nonunits=[] and nonperp=[]);
